from pathlib import Path
import re

transport_path=Path('js/modules/transport.js')
src=transport_path.read_text()
start=src.index('function studentOptions(')
end=src.index('async function openClassSeating(id)',start)
block=r'''function seatStudentName(e){return arr('veliler').find(v=>v.id===e.studentId)?.ogrenciAdi||e.properties?.studentName||''}
function busSeatPosition(e){const p=String(e?.properties?.konum||'').trim();return ['sol-dis','sol-ic','sag-ic','sag-dis'].includes(p)?`is-${p}`:''}
function busSeatState(e){const name=seatStudentName(e);return name?'is-filled':e?.properties?.reserved?'is-reserved':'is-empty'}
function busSeatInitial(name){return String(name||'').trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toLocaleUpperCase('tr')||'+'}
function busSeatShortName(name){const parts=String(name||'').trim().split(/\s+/).filter(Boolean);return parts.length>1?`${parts[0]} ${parts.at(-1)[0]}.`:parts[0]||'Boş'}
function busSeatTile(e,index){
  const name=seatStudentName(e),state=busSeatState(e),pos=busSeatPosition(e),reserved=e?.properties?.reserved&&!name;
  const content=`<span class="ka-bus-seat__number">${esc(e.seatNumber||index+1)}</span><span class="ka-bus-seat__avatar">${reserved?'R':esc(busSeatInitial(name))}</span><span class="ka-bus-seat__name">${reserved?'Rezerve':esc(busSeatShortName(name))}</span>`;
  return editor?.editable?`<button class="ka-bus-seat ${state} ${pos}" type="button" data-bus-seat-index="${index}" aria-label="Koltuk ${esc(e.seatNumber||index+1)}${name?': '+esc(name):reserved?': Rezerve':': Boş'}">${content}</button>`:`<div class="ka-bus-seat ${state} ${pos}" aria-label="Koltuk ${esc(e.seatNumber||index+1)}${name?': '+esc(name):reserved?': Rezerve':': Boş'}">${content}</div>`;
}
function busCabinHtml(){
  if(!editor)return '';
  const active=editor.elements.map((e,index)=>({e,index})).filter(x=>x.e?.visible!==false),driver=active.find(x=>x.e.type==='sofor'),seats=active.filter(x=>x.e.type!=='sofor'),rear=seats.filter(x=>x.e.type==='arka-koltuk'||x.e.properties?.konum==='arka'),regular=seats.filter(x=>!rear.includes(x));
  const rows=new Map();regular.forEach(x=>{const row=Number.isFinite(Number(x.e.row))?Number(x.e.row):0;if(!rows.has(row))rows.set(row,[]);rows.get(row).push(x)});
  const isTwoTwo=['buyuk','midibus'].includes(editor.sablon);
  const body=[...rows.entries()].sort((a,b)=>a[0]-b[0]).map(([row,items],ri)=>{const hasSagIc=items.some(x=>x.e.properties?.konum==='sag-ic');return `<div class="ka-bus-row-wrap"><span class="ka-bus-row-label">${ri+1}</span><div class="ka-bus-row ${hasSagIc?'has-sag-ic':''}">${items.map(x=>busSeatTile(x.e,x.index)).join('')}<span class="ka-bus-aisle" aria-hidden="true"></span></div></div>`}).join('');
  const rearHtml=rear.length?`<div class="ka-bus-row-wrap ka-bus-rear-wrap"><span class="ka-bus-row-label">Arka</span><div class="ka-bus-rear-row">${rear.map(x=>busSeatTile(x.e,x.index)).join('')}</div></div>`:'';
  return `<div class="ka-bus-cabin ${isTwoTwo?'is-2plus2':'is-2plus1'}"><div class="ka-bus-front"><div class="ka-bus-driver"><span>🚐</span><small>${driver?'Şoför':'Ön'}</small></div><strong class="ka-bus-front-label">ARAÇ ÖNÜ</strong><div class="ka-bus-door">KAPI</div></div><div class="ka-bus-cabin__body">${body}${rearHtml||''}</div></div>`;
}
function busHasAssignments(){return !!editor?.elements?.some(e=>e.studentId||e.properties?.reserved)}
function clearBusSeat(e){if(!e)return;e.studentId=null;e.properties={...(e.properties||{}),studentName:'',reserved:false}}
function assignedBusSeat(studentId,except=-1){if(!studentId||!editor)return null;const i=editor.elements.findIndex((e,idx)=>idx!==except&&e.studentId===studentId);return i<0?null:editor.elements[i]}
function assignBusStudent(index,studentId){
  if(!editor?.editable)return false;
  const target=editor.elements[index],person=students(editor.servisId).find(v=>v.id===studentId);if(!target||!person)return false;
  editor.elements.forEach((e,idx)=>{if(idx!==index&&e.studentId===person.id)clearBusSeat(e)});
  target.studentId=person.id;target.properties={...(target.properties||{}),studentName:person.ogrenciAdi||'',reserved:false};return true;
}
function openBusSeatPicker(index,s){
  if(!editor?.editable)return;
  const host=document.getElementById('transportBusEditor'),seat=editor.elements[index];if(!host||!seat)return;
  host.querySelector('[data-bus-seat-picker]')?.remove();
  const picker=document.createElement('div');picker.className='ka-modal-backdrop ka-bus-seat-picker';picker.dataset.busSeatPicker='';
  const renderOptions=term=>{const q=norm(term),list=students(editor.servisId).filter(v=>!q||norm([v.ogrenciAdi,v.ogrenciNo,className(v.sinifId)].join(' ')).includes(q));return list.length?list.map(v=>{const assigned=assignedBusSeat(v.id,index);return `<button class="ka-bus-student-option" type="button" data-bus-student="${esc(v.id)}"><span class="ka-bus-student-option__avatar">${esc(busSeatInitial(v.ogrenciAdi))}</span><span class="ka-grow"><strong>${esc(v.ogrenciAdi||'Öğrenci')}</strong><small>${esc([className(v.sinifId),v.ogrenciNo?`No: ${v.ogrenciNo}`:'',assigned?`Koltuk ${assigned.seatNumber||'?'}`:''].filter(Boolean).join(' · '))}</small></span>${v.id===seat.studentId?'<span class="ka-badge ka-badge--success">Seçili</span>':''}</button>`}).join(''):'<div class="ka-empty">Uygun öğrenci bulunamadı.</div>'};
  picker.innerHTML=`<section class="ka-modal ka-bus-seat-picker__modal"><div class="ka-modal__header"><div><h3>Koltuk ${esc(seat.seatNumber||index+1)}</h3><div class="ka-muted">${esc(seatStudentName(seat)||(seat.properties?.reserved?'Rezerve':'Öğrenci seçin'))}</div></div><button class="ka-icon-button" type="button" data-bus-picker-close>×</button></div><div class="ka-modal__body ka-stack"><label class="ka-field"><span class="ka-field__label">Öğrenci ara</span><input type="search" data-bus-student-search placeholder="Ad, numara veya sınıf…" autocomplete="off"></label><div class="ka-bus-student-list" data-bus-student-list>${renderOptions('')}</div></div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-bus-seat-clear>Boşalt</button><button class="ka-btn ka-btn--secondary" type="button" data-bus-seat-reserve>${seat.properties?.reserved&&!seat.studentId?'Rezervasyonu Kaldır':'Rezerve Et'}</button><button class="ka-btn ka-btn--secondary" type="button" data-bus-picker-close>Kapat</button></div></section>`;
  host.appendChild(picker);
  const closePicker=()=>picker.remove();
  picker.querySelectorAll('[data-bus-picker-close]').forEach(b=>b.onclick=closePicker);
  const bindStudents=()=>picker.querySelectorAll('[data-bus-student]').forEach(b=>b.onclick=()=>{if(assignBusStudent(index,b.dataset.busStudent)){closePicker();renderBusEditor(s)}});
  bindStudents();
  picker.querySelector('[data-bus-student-search]').oninput=e=>{picker.querySelector('[data-bus-student-list]').innerHTML=renderOptions(e.target.value);bindStudents()};
  picker.querySelector('[data-bus-seat-clear]').onclick=()=>{clearBusSeat(seat);closePicker();renderBusEditor(s)};
  picker.querySelector('[data-bus-seat-reserve]').onclick=()=>{const next=!(seat.properties?.reserved&&!seat.studentId);clearBusSeat(seat);seat.properties={...(seat.properties||{}),reserved:next};closePicker();renderBusEditor(s)};
}
function openBusEditor(servisId){const s=arr('servisler').find(x=>x.id===servisId);if(!s)return;const p=currentPlan(servisId)||{},sablon=p.sablon||'ducato',elements=window.soPlanElementleriGetir?.(p,sablon)||[];editor={servisId,sablon,elements,editable:canEditBusSeats()};renderBusEditor(s)}
function renderBusEditor(s){
  if(!editor)return;document.getElementById('transportBusEditor')?.remove();
  const st=window.soElementIstatistik?.(editor.elements)||{toplam:0,dolu:0,bos:0,rezerve:0,doluluk:0},editable=editor.editable;
  const templates=editable?Object.entries(window.SO_SABLONLAR||{}).map(([k,v])=>`<option value="${esc(k)}" ${k===editor.sablon?'selected':''}>${esc(v.ikon+' '+v.ad)}</option>`).join(''):'';
  const ov=document.createElement('div');ov.id='transportBusEditor';ov.className='ka-modal-backdrop ka-bus-editor-backdrop';
  ov.innerHTML=`<section class="ka-modal ka-bus-editor-modal"><div class="ka-modal__header"><div><strong>${esc(serviceName(s))}</strong><div class="ka-muted">Servis oturma planı · ${editable?'Koltuğa dokunarak öğrenci yerleştirin':'Salt okunur'}</div></div><button class="ka-btn ka-btn--secondary ka-btn--sm" data-bus-close type="button">Kapat</button></div><div class="ka-modal__body ka-stack"><div class="ka-bus-editor-top">${editable?`<label class="ka-field"><span class="ka-field__label">Araç şablonu</span><select id="busTemplateSelect">${templates}</select></label>`:`<div><span class="ka-muted">Araç şablonu</span><strong>${esc(window.SO_SABLONLAR?.[editor.sablon]?.ad||editor.sablon||'Araç')}</strong></div>`}<div class="ka-bus-editor-summary"><div><strong>${st.toplam}</strong><span>Koltuk</span></div><div><strong>${st.dolu}</strong><span>Dolu</span></div><div><strong>${st.bos}</strong><span>Boş</span></div><div><strong>${st.rezerve||0}</strong><span>Rezerve</span></div></div></div><div class="ka-bus-legend"><span><i class="is-empty"></i>Boş</span><span><i class="is-filled"></i>Dolu</span><span><i class="is-reserved"></i>Rezerve</span></div>${busCabinHtml()}</div>${editable?'<div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" data-bus-clear-all type="button">Atamaları Temizle</button><button class="ka-btn ka-btn--secondary" data-bus-reset type="button">Şablonu Sıfırla</button><button class="ka-btn" data-bus-save type="button">Kaydet</button></div>':''}</section>`;
  document.body.appendChild(ov);bindEditor(ov,s)
}
function closeEditor(){document.getElementById('transportBusEditor')?.remove();editor=null}
function newElements(sablon){const layout=window.SO_SABLONLAR?.[sablon]?.yerlesimUret?.()||[];let no=0;return layout.map((yuva,idx)=>{const driver=!!yuva.soforYani;if(!driver)no++;return{id:'el_'+(idx+1),type:driver?'sofor':yuva.konum==='arka'?'arka-koltuk':'koltuk',seatNumber:driver?null:no,studentId:null,row:yuva.sira,column:idx,locked:false,visible:yuva.aktif!==false,color:null,properties:{konum:yuva.konum||'',kapiSag:!!yuva.kapiSag,soforYani:driver,studentName:'',stop:'',note:'',reserved:false}}})}
function bindEditor(ov,s){
  ov.querySelector('[data-bus-close]').onclick=closeEditor;if(!editor?.editable)return;
  ov.querySelector('#busTemplateSelect').onchange=e=>{const next=e.target.value;if(next===editor.sablon)return;if(busHasAssignments()&&!confirm('Araç şablonu değişirse mevcut koltuk atamaları temizlenecek. Devam edilsin mi?')){e.target.value=editor.sablon;return}editor.sablon=next;editor.elements=newElements(next);renderBusEditor(s)};
  ov.querySelectorAll('[data-bus-seat-index]').forEach(btn=>btn.onclick=()=>openBusSeatPicker(Number(btn.dataset.busSeatIndex),s));
  ov.querySelector('[data-bus-clear-all]').onclick=()=>{if(!busHasAssignments())return;if(!confirm('Tüm öğrenci ve rezervasyon atamaları temizlensin mi? Koltuk düzeni korunacak.'))return;editor.elements.forEach(clearBusSeat);renderBusEditor(s)};
  ov.querySelector('[data-bus-reset]').onclick=()=>{if(!confirm('Seçili araç şablonu varsayılan koltuk düzenine döndürülsün mü?'))return;editor.elements=newElements(editor.sablon);renderBusEditor(s)};
  ov.querySelector('[data-bus-save]').onclick=async()=>{if(!canEditBusSeats()){toast?.('Öğretmen kullanıcıları servis oturma planını yalnız görüntüleyebilir.');return}const b=ov.querySelector('[data-bus-save]');b.disabled=true;b.textContent='Kaydediliyor…';try{await window.ServisOturmaService.planElementsKaydet(editor.servisId,editor.sablon,editor.elements,false);toast?.('Oturma planı cihazda kaydedildi.');closeEditor();render()}catch(e){toast?.('Plan kaydedilemedi: '+(e?.message||e));b.disabled=false;b.textContent='Kaydet'}}
}
'''
transport_path.write_text(src[:start]+block+src[end:])

